48	/** RFC-4180 compliant CSV row parser — handles quoted fields containing commas. */
49	function parseCsvRow(line: string): string[] {
50	  const cols: string[] = [];
51	  let cur = "";
52	  let inQuotes = false;
53	  for (let i = 0; i < line.length; i++) {
54	    const ch = line[i];
55	    if (ch === '"') {
56	      if (inQuotes && line[i + 1] === '"') {
57	        cur += '"';
58	        i++;
59	      } else {
60	        inQuotes = !inQuotes;
61	      }
62	    } else if (ch === "," && !inQuotes) {
63	      cols.push(cur.trim());
64	      cur = "";
65	    } else {
66	      cur += ch;
67	    }
68	  }
69	  cols.push(cur.trim());
70	  return cols;
71	}
