74	function downloadSampleCsv() {
75	  const sample = [
76	    "Zip Code,Zone,Status,Message,ETA,COD,Return Policy",
77	    "10001,Manhattan,allowed,We deliver here! Estimated 2-3 days.,2-3 days,Yes,30-day returns accepted",
78	    "90210,Beverly Hills,allowed,Same day delivery available.,1 day,No,",
79	    "33101,Miami,blocked,Sorry we do not deliver to this area.,,",
80	  ].join("\n");
81	  const blob = new Blob([sample], { type: "text/csv" });
82	  const url = URL.createObjectURL(blob);
83	  const a = document.createElement("a");
84	  a.href = url;
85	  a.download = "sample-zip-codes.csv";
86	  a.click();
87	  URL.revokeObjectURL(url);
88	}
