90	export const loader = async ({ request }: LoaderFunctionArgs) => {
91	  const { session } = await authenticate.admin(request);
92	  const shop = session.shop;
93	
94	  const [zipCodes, subscription] = await Promise.all([
95	    db.zipCode.findMany({
96	      where: { shop },
97	      orderBy: { createdAt: "desc" },
98	    }),
99	    getShopSubscription(shop),
100	  ]);
101	
102	  const stats = {
103	    total: zipCodes.length,
104	    allowed: zipCodes.filter((z) => z.type === "allowed").length,
105	    blocked: zipCodes.filter((z) => z.type === "blocked").length,
106	    active: zipCodes.filter((z) => z.isActive).length,
107	  };
108	
109	  return { zipCodes, stats, subscription };
110	};
