506	
507	  if (intent === "range-import") {
508	    const startZip = String(formData.get("startZip") || "").trim().toUpperCase();
509	    const endZip = String(formData.get("endZip") || "").trim().toUpperCase();
510	    const zone = (formData.get("zone") as string | null) || null;
511	    // Sanitize type — only accept known values, default to "allowed"
512	    const type = String(formData.get("type") || "") === "blocked" ? "blocked" : "allowed";
513	    const message = (formData.get("message") as string | null) || null;
514	    const eta = (formData.get("eta") as string | null) || null;
515	
516	    // Validate: must be 5-digit numeric zips
517	    const ZIP_RE = /^\d{5}$/;
518	    if (!ZIP_RE.test(startZip) || !ZIP_RE.test(endZip)) {
519	      return { error: "ZIP range import only supports 5-digit US ZIP codes (e.g., 10001)." };
520	    }
521	
522	    const start = parseInt(startZip, 10);
523	    const end = parseInt(endZip, 10);
524	
525	    if (end < start) {
526	      return { error: "End ZIP must be greater than or equal to Start ZIP." };
527	    }
528	
529	    const rangeSize = end - start + 1;
530	    const MAX_RANGE = 500;
531	    if (rangeSize > MAX_RANGE) {
532	      return { error: `Range too large. Maximum ${MAX_RANGE} zip codes per import (got ${rangeSize}).` };
533	    }
534	
535	    try {
536	      // Check plan limits
537	      const subscription = await getShopSubscription(shop);
538	      const limits = PLAN_LIMITS[subscription.planTier];
539	
540	      if (!limits.csvImport) {
541	        const upgradeTarget =
542	          subscription.planTier === "free" ? "Starter" : "Pro";
543	        return {
544	          error: `ZIP range import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to use bulk import features.`,
545	          upgradeRequired: true,
546	        };
547	      }
548	
549	      if (type === "blocked" && !limits.allowBlocked) {
550	        return {
551	          error: "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
552	          upgradeRequired: true,
553	        };
554	      }
555	
556	      const currentCount = await db.zipCode.count({ where: { shop } });
557	      if (limits.maxZipCodes < UNLIMITED && currentCount + rangeSize > limits.maxZipCodes) {
558	        const upgradeTarget =
559	          subscription.planTier === "free" ? "Starter" : "Pro";
560	        return {
561	          error: `This range would exceed your ${limits.label} plan limit of ${limits.maxZipCodes} zip codes. You have ${limits.maxZipCodes - currentCount} slots remaining. Upgrade to ${upgradeTarget} for a higher limit.`,
562	          upgradeRequired: true,
563	        };
564	      }
565	
566	      // Build all zip records for the range
567	      const zipRecords = Array.from({ length: rangeSize }, (_, i) => ({
568	        shop,
569	        zipCode: String(start + i).padStart(5, "0"),
570	        zone: zone ?? undefined,
571	        type,
572	        message: message ?? undefined,
573	        eta: eta ?? undefined,
574	      }));
575	
576	      // Use createMany with skipDuplicates — much faster than N sequential upserts.
577	      // For existing records (skipDuplicates), we do a follow-up updateMany to refresh
578	      // zone/type/message/eta so the import always reflects the submitted values.
579	      const created = await db.zipCode.createMany({
580	        data: zipRecords,
581	        skipDuplicates: true,
582	      });
583	
584	      // Update any already-existing records in the range to apply the new values
585	      await db.zipCode.updateMany({
586	        where: {
587	          shop,
588	          zipCode: { in: zipRecords.map((r) => r.zipCode) },
589	        },
590	        data: {
591	          zone: zone ?? undefined,
592	          type,
593	          message: message ?? undefined,
594	          eta: eta ?? undefined,
595	        },
596	      });
597	
598	      return { success: true, action: "range-import", imported: created.count, total: rangeSize };
599	    } catch {

600	      return { error: "Failed to import ZIP code range. Please try again." };
601	    }
602	  }
603	
604	  // Unknown intent
605	  return { error: "Unknown action." };
606	};
