        <TextField
          label="Start ZIP"
          value={rangeStart}
          onChange={setRangeStart}
          placeholder="10001"
          autoComplete="off"
          maxLength={5}
        />
        <TextField
          label="End ZIP"
          value={rangeEnd}
          onChange={setRangeEnd}
          placeholder="10099"
          autoComplete="off"
          maxLength={5}
        />
      </InlineGrid>
      <Select
        label="Status"
        options={typeOptions}
        value={rangeType}
        onChange={setRangeType}
      />
      <TextField
        label="Zone (optional)"
        value={rangeZone}
        onChange={setRangeZone}
        placeholder="Manhattan"
        autoComplete="off"
        helpText="Group these ZIP codes under a zone name."
      />
      <TextField
        label="Delivery Message (optional)"
        value={rangeMessage}
        onChange={setRangeMessage}
        placeholder="We deliver to your area!"
        autoComplete="off"
      />
      <TextField
        label="ETA (optional)"
        value={rangeEta}
        onChange={setRangeEta}
        placeholder="2-3 business days"
        autoComplete="off"
      />
    </BlockStack>
  </Modal.Section>
</Modal>

